def Saisie():
    b = False
    while not b:
        ch = str(input('Donner l\'adresse mail: '))
        b, p = verif(ch)  # p désigne la position de '@' dans la chaine
    return ch, p


def verif(ch):
    V = {'.', '_', '-'}
    S = 0
    for i in range(len(ch)):
        if ch[i] == '@':
            S += 1
    p = ch.find('@')
    R = ch[:p]
    ok = S == 1 and "A" <= ch[0].upper() <= "Z"
    i = -1
    while i < len(R) - 1 and ok == True:
        i += 1
        ok = "A" <= R[i].upper() <= "Z" or '0' <= R[i] <= '9' or R[i] in V
    return ok, p


def mot_de_passe(ch, p):
    R = ch[:p] + ch[p + 1] + ch[len(ch) - 1]
    return R


ch, p = Saisie()
mdp = mot_de_passe(ch, p)
print(mdp)

